create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.CHARGE_IST_QA_CHECK_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_2 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	LAGERNUMMER_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Lagernummer/-komplex - Feld LGNUM',
	TOUR_ID NUMBER(18,0) NOT NULL COMMENT 'Transportnummer, analog zu VVTK/VTTP.TKNUM bzw. tour_2/tour_det.tour_id - Feld TKNUM',
	LIEF_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Vertriebsbelegnummer, analog zu LIPS.VBELN bzw. besch_lief_2/besch_lief_det.lief_beleg_id - Feld VBELN',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Kontonummer des Lieferanten bzw. Kreditors - Feld LIFNR',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer - Feld MATNR',
	CHARGE_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Chargennummer, analog zu qa_check_og.charge_id - Feld CHARG',
	CHARGE_NR_QA VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Chargennummer, die bei einer QS-Meldung erzeugt wird  / QA steht für O&G, PF für Pflanzen, FL für Fleischwerk -> aber nicht zwingend - Feld CHARG_QA',
	KALIBER_KZ_IST VARCHAR(4) COLLATE 'en-ci' COMMENT 'Kaliber des Produktes IST: Größe, Gewicht o.Ä. - Feld CALIBER_UNIT',
	FREITEXT_QA_KOMMENTAR_IST VARCHAR(180) COLLATE 'en-ci' COMMENT 'freitext_qa_kommentar_ist',
	URSPRUNGSLAND_KBEZ_IST VARCHAR(4) COLLATE 'en-ci' COMMENT 'Ursprungsland/Länderschlüssel, bspw. DE oder NZ - Feld URZLA',
	ZUS_URSPRUNGSLAENDER_KBEZ_IST VARCHAR(16) COLLATE 'en-ci' COMMENT 'weitere Ursprungslänger/Sign O+G, bspw. BE, GR oder NL - Feld SIGNO',
	DEFEKTE_KOLLI_IST NUMBER(38,0) COMMENT 'Anzahl der defekten Kolli - Feld DEFECT_KOLLIS',
	HANDELSKLASSE_IST_KZ VARCHAR(1) COLLATE 'en-ci' COMMENT 'Information zur Handelsklasse, 0 steht für HKL0, 1 für HKL1,… - Feld HKL',
	FREITEXT_LIEFERANTEN_KOMMENTAR_IST VARCHAR(180) COLLATE 'en-ci' COMMENT 'Freitextfeld: Information für den Lieferant (IST) / Vorgabe vom Einkäufer an den Lieferanten und damit Inhalt, der im WE geprüft wird - Feld KOMMENTAR_LIEFERANT',
	FREITEXT_PRIMAERVERPACKUNG_IST VARCHAR(30) COLLATE 'en-ci' COMMENT 'Freitextfeld: Verpackung, wie sie im Laden für den Kunden steht - Feld KUNDEN_PACK',
	UNBEHANDELT_IST_KZ VARCHAR(1) COLLATE 'en-ci' COMMENT 'KZ das angibt, ob O&G behandelt oder unbehandelt ist, bspw. U für unbehandelt - Feld KZBEH',
	TRANSPORT_VERPACKUNG_KMO_IST_KZ VARCHAR(2) COLLATE 'en-ci' COMMENT 'Zweistelliges KZ über Transportverpackung, bspw. KA für Karton - Feld KZPACK',
	FREITEXT_MARKE_IST VARCHAR(60) COLLATE 'en-ci' COMMENT 'Freitextfeld: Marke des Artikels (IST) - Feld MARKE',
	MENGE_STICHPROBE_FRISCHEMAENGEL NUMBER(18,3) COMMENT 'Wieviel Stück / KG wurden in der Stichprobe mit Frischemangel gefunden - Feld AMOUNT_DEFECT_MAJOR ',
	MENGE_STICHPROBE_SONSTIGES NUMBER(18,3) COMMENT 'Wieviel Stück / KG wurden in der Stichprobe mit sonstigen Mängeln gefunden - Feld AMOUNT_DEFECT_MINOR',
	NETTOINHALT_KOLLI_IST NUMBER(18,3) COMMENT 'Durchführung Stichprobe (IST) - Sind in 500g Schale auch 500g enthalten? Bei Artikeln ohne Prüfmöglichkeit/Prüfung steht hier eine_2 0 - Feld NTGEW',
	FREITEXT_FRUCHTFLEISCHDRUCK_IST VARCHAR(30) COLLATE 'en-ci' COMMENT 'Freitextfeld: Sagt aus, wie fest Fruchtfleisch ist wenn man die Frucht eindrückt - Feld DRUCK (SAP-Feld wurde früher für etwas anderes genutzt (früher wurden Preise auf das Etikett angedrückt), Feldname wurde in SAP nie angepasst)',
	FREITEXT_PRODUZENT_IST VARCHAR(30) COLLATE 'en-ci' COMMENT 'Freitextfeld: Produzent des Artikels (IST) - Feld PRODUCER',
	FREITEXT_HINWEIS_FUER_QA_IST VARCHAR(110) COLLATE 'en-ci' COMMENT 'Freitextfeld: Hinweis für den Kontrolleur - Feld QA_COMMENT',
	FREITEXT_SAFTGEHALT_IST VARCHAR(30) COLLATE 'en-ci' COMMENT 'Freitextfeld: Sagt etwas über den Saftgehalt des Artikels aus - Feld REGIONAL_PACK (SAP-Feld wurde früher für etwas anderes genutzt, Feldname wurde in SAP nie angepasst)',
	ANZ_KOLLI_GEPRUEFT_IST NUMBER(38,0) COMMENT 'Anzahl der geprüften Kolli - Feld SAMPLE_KOLLIS',
	FREITEXT_SPEZIFIKATION_IST VARCHAR(110) COLLATE 'en-ci' COMMENT 'Freitextfeld: Spezifikation - Feld Spezifikation',
	FREITEXT_TEMPERATUR_CHECK_IST VARCHAR(20) COLLATE 'en-ci' COMMENT 'Freitextfeld: Temperatur mit der die Ware ankommt - Feld TEMPERATURE',
	FREITEXT_BESONDERHEITEN_IST VARCHAR(30) COLLATE 'en-ci' COMMENT 'Freitextfeld: Besonderheiten (IST), z.B. bei einer Mango - Ist sie vorgereift? Kann das Stück auch mal mehr als 250 Gramm haben? - Feld TEXT',
	FREITEXT_TRANSPORT_VERPACKUNG_DE_IST VARCHAR(15) COLLATE 'en-ci' COMMENT 'Freitextfeld: Transportverpackung, nur für DE gefüllt, bspw. LIN oder KARTON - Feld VERPACKTRANS',
	KONTROLLNOTWENDIGKEIT_VORERNTENUMMER_IST_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für QS, sagt aus ob Vorerntenummer kontrolliert wurde - Feld VORERNTE',
	PALETTENFAKTOR_IST NUMBER(38,0) COMMENT 'Pallettenfaktor/Menge in Paletten, bspw. 100 oder 60 - Feld MENGEP',
	VERTRAGSANBAU_IST_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag das aussagt, ob es Vertragsanbau gibt - Feld CONTRACT_FRAMING',
	NATIONALE_PRODUKTION_IST_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag das aussagt, ob Produkt einer nationalen Produktion unterliegt - Feld NATIONAL_PROD',
	KALIBER_VON_IST NUMBER(38,0) COMMENT 'Kaliber, Größe, Gewicht von, bspw. 800 - Feld KALVON',
	KALIBER_BIS_IST NUMBER(38,0) COMMENT 'Kaliber, Größe, Gewicht bis, bspw. 1000 - Feld KALBIS',
	FREITEXT_FRUCHTGEHALT_IST VARCHAR(20) COLLATE 'en-ci' COMMENT 'Freitextfeld: Zuckergehalt des Artikels - Feld SALES_UNIT',
	DAT_EMPFANG DATE COMMENT 'Empfangsdatum - Feld RECEIVE_DATE',
	DAT_ANTWORT DATE COMMENT 'Antwortdatum - Feld RESPONSE_DATE',
	ZEIT_ANTWORT TIMESTAMP_LTZ(9) COMMENT 'Antwortzeit - Feld RESPONSE_DATE',
	DAT_AENDERUNG DATE NOT NULL DEFAULT (1900 - 1) - 1 COMMENT 'Änderungsdatum, Datum an dem der Satz hinzugefügt wurde - Feld AEDAT',
	ANZ_KOLLI NUMBER(18,3) COMMENT 'Anzahl Kolli - Feld KOLLI',
	QA_STATUS VARCHAR(2) COLLATE 'en-ci' COMMENT 'QA Status_2, bspw. A für Konzession, R für Verweigerung, S für Annahme - Feld QA_STATUS',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	ANZ_KOLLI_IST NUMBER(38,0) COMMENT 'Kollianzahl IST- Feld QA_MENGEP',
	CHARGE_VORHANDEN_IST_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag, das aussagt, ob eine_2 Charge vorhanden ist - Feld CHARGE_VORHANDEN',
	LIEFERANT_CHARGE_NR VARCHAR(15) COMMENT 'Lieferantenchargennummer',
	GTIN_VORHANDEN_FG NUMBER(38,0) COMMENT 'Flag, welche aussagt, ob eine_2 GTIN für den Artikel_2 vorhanden (1) ist oder nicht (0).',
	DATZEIT_EINGANG TIMESTAMP_LTZ(9) COMMENT 'Eingangszeitstempel der QA-Meldung',
	constraint PK_CHARGE_IST_QA_CHECK primary key (MANDANT_ID, WUP_ID, NB_ID, LAGERNUMMER_ID, TOUR_ID, LIEF_BELEG_ID, GP_ID, ART_ID, CHARGE_ID, CHARGE_NR_QA)
)COMMENT='SAP RET INT ZLV_QA_OG_ACT - enthält die O&G Chargenwerte, die an das VZ geliefert werden (IST), z.B. Äpfel in der Größe 75mm_2 - ZOG_CHAR bzw. charge_ist bildet das SOLL ab'
;
